client_script:
frappe.web_form.after_load = function() {
  if (frappe.web_form.fields_dict.chef_equipe) { frappe.web_form.fields_dict.chef_equipe.get_query = function(){ return { query: 'kya_hr.api.delegataire_query' }; }; }
  var doc = frappe.web_form.doc;
  if (doc && (!doc.chef_equipe) && window.frappe && frappe.session) {
    frappe.call({ method:'frappe.client.get_value', args:{ doctype:'Employee', filters:{ user_id: frappe.session.user, status:'Active' }, fieldname:['name','department'] }, callback:function(r){ if(r.message){ frappe.web_form.set_value('chef_equipe', r.message.name); if(r.message.department && !doc.equipe) frappe.web_form.set_value('equipe', r.message.department); } } });
  }
  if (doc && !doc.annee) { frappe.web_form.set_value('annee', new Date().getFullYear()); }
  if (doc && doc.name && !String(doc.name).startsWith('new')) {
    var st = doc.statut || 'Brouillon';
    var cm = {'Brouillon':'#757575','Soumis \u00e0 la RH':'#1565c0','En revue RH':'#e65100','Trait\u00e9':'#2e7d32'};
    var c = cm[st] || '#1565c0';
    var el = document.createElement('div');
    el.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:'+c+';color:#fff;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">\uD83C\uDF93 ' + doc.name + '  \u2014  ' + st + '</div>';
    var w = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w) w.prepend(el);
  }
};
